#[test]
fn traces_csharp_nested_constructed_generic_receiver_property_chain_var_array_element_access_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let db_path = dir.join("symbols.db");
    fs::write(
        dir.join("Types.cs"),
        "namespace Demo;
class HelperA { public int RunA(int value) => value; }
class HelperB { public int RunB(int value) => value; }
class Outer<T> {
    public class Inner<U> {
        public U[] Items => default;
        public T[] OuterItems => default;
    }
}
class Caller {
    int Direct() { return new Outer<HelperA>.Inner<HelperB>().Items[0].RunB(1); }
    int Var() { var arr = new Outer<HelperA>.Inner<HelperB>().Items; return arr[0].RunB(2); }
    int VarOuter() { var arr = new Outer<HelperA>.Inner<HelperB>().OuterItems; return arr[0].RunA(3); }
    int VarSame() { var arr = new Outer<HelperA>.Inner<HelperA>().Items; return arr[0].RunA(4); }
    int VarB() { var arr = new Outer<HelperB>.Inner<HelperB>().Items; return arr[0].RunB(5); }
}
",
    )
    .unwrap();

    // A nested constructed generic receiver such as
    // `new Outer<HelperA>.Inner<HelperB>().Items` keeps the dotted type path
    // together in the `@init:` chain so a `var` local bound from the property
    // chain dispatches element access on the inner type parameter (`U` ->
    // `HelperB` in `U[] Items`) while an outer-parameter member (`T[]`
    // OuterItems`) substitutes the outer argument (`T` -> `HelperA`), and the
    // direct chain resolves the same way; mismatched concrete arguments
    // dispatch on the matching helper type.
    let run_a_live =
        trace_symbol_graph(&dir, "Demo::HelperA::RunA", TraceDirection::Callers).unwrap();
    assert_eq!(run_a_live.callers.len(), 2);
    for caller in ["Demo::Caller::VarOuter", "Demo::Caller::VarSame"] {
        assert!(
            run_a_live
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing live caller {caller}"
        );
    }
    let run_b_live =
        trace_symbol_graph(&dir, "Demo::HelperB::RunB", TraceDirection::Callers).unwrap();
    assert_eq!(run_b_live.callers.len(), 3);
    for caller in [
        "Demo::Caller::Direct",
        "Demo::Caller::Var",
        "Demo::Caller::VarB",
    ] {
        assert!(
            run_b_live
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing live caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let run_a_persisted =
        trace_symbol_graph_from_index(&db_path, "Demo::HelperA::RunA", TraceDirection::Callers)
            .unwrap();
    assert_eq!(run_a_persisted.callers.len(), 2);
    for caller in ["Demo::Caller::VarOuter", "Demo::Caller::VarSame"] {
        assert!(
            run_a_persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    let run_b_persisted =
        trace_symbol_graph_from_index(&db_path, "Demo::HelperB::RunB", TraceDirection::Callers)
            .unwrap();
    assert_eq!(run_b_persisted.callers.len(), 3);
    for caller in [
        "Demo::Caller::Direct",
        "Demo::Caller::Var",
        "Demo::Caller::VarB",
    ] {
        assert!(
            run_b_persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
}

#[test]
fn traces_csharp_nested_constructed_generic_receiver_member_chain_var_array_element_access_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let db_path = dir.join("symbols.db");
    fs::write(
        dir.join("Types.cs"),
        "namespace Demo;
class HelperA { public int RunA(int value) => value; }
class HelperB { public int RunB(int value) => value; }
class Outer<T> {
    public class Inner<U> {
        public U[] Items => default;
        public T[] OuterItems => default;
        public U[] MakeItems() => Items;
        public Inner<U> Next => default;
        public Inner<U> MakeNext() => Next;
        public Inner<U>[] NextArray => default;
    }
}
class PlainOuter {
    public class PlainInner {
        public HelperA[] Items => default;
        public PlainInner Next => default;
        public PlainInner MakeNext() => Next;
    }
}
class Caller {
    int DirectPropChain() { return new Outer<HelperA>.Inner<HelperB>().Next.Items[0].RunB(1); }
    int DirectMethodChain() { return new Outer<HelperA>.Inner<HelperB>().MakeNext().Items[0].RunB(2); }
    int DirectMethodOuter() { return new Outer<HelperA>.Inner<HelperB>().MakeNext().OuterItems[0].RunA(3); }
    int VarPropChain() { var arr = new Outer<HelperA>.Inner<HelperB>().Next.Items; return arr[0].RunB(4); }
    int VarMethodChain() { var arr = new Outer<HelperA>.Inner<HelperB>().MakeNext().Items; return arr[0].RunB(5); }
    int VarMethodOuter() { var arr = new Outer<HelperA>.Inner<HelperB>().MakeNext().OuterItems; return arr[0].RunA(6); }
    int VarNextArray() { var arr = new Outer<HelperA>.Inner<HelperB>().NextArray; return arr[0].MakeNext().Items[0].RunB(7); }
    int PlainDirectProp() { return new PlainOuter.PlainInner().Next.Items[0].RunA(8); }
    int PlainVarProp() { var arr = new PlainOuter.PlainInner().Next.Items; return arr[0].RunA(9); }
    int PlainDirectMethod() { return new PlainOuter.PlainInner().MakeNext().Items[0].RunA(10); }
}
",
    )
    .unwrap();

    // A nested constructed generic receiver such as
    // `new Outer<HelperA>.Inner<HelperB>().MakeNext().Items` keeps the dotted
    // type path together in the `@init:` chain and resolves intermediate
    // property (`Next`) and method-call (`MakeNext()`) hops on the
    // constructed nested type, so a `var` local bound from the chain
    // dispatches element access on the substituted inner type parameter
    // (`U` -> `HelperB`), an outer-parameter member (`T[] OuterItems`)
    // substitutes the outer argument (`T` -> `HelperA`), and array-typed
    // hops (`Inner<U>[] NextArray`) continue through element access; the
    // same chains resolve non-generic nested types (`PlainOuter.PlainInner`)
    // and direct chains identically.
    let run_a_live =
        trace_symbol_graph(&dir, "Demo::HelperA::RunA", TraceDirection::Callers).unwrap();
    assert_eq!(run_a_live.callers.len(), 5);
    for caller in [
        "Demo::Caller::DirectMethodOuter",
        "Demo::Caller::VarMethodOuter",
        "Demo::Caller::PlainDirectProp",
        "Demo::Caller::PlainVarProp",
        "Demo::Caller::PlainDirectMethod",
    ] {
        assert!(
            run_a_live
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing live caller {caller}"
        );
    }
    let run_b_live =
        trace_symbol_graph(&dir, "Demo::HelperB::RunB", TraceDirection::Callers).unwrap();
    assert_eq!(run_b_live.callers.len(), 5);
    for caller in [
        "Demo::Caller::DirectPropChain",
        "Demo::Caller::DirectMethodChain",
        "Demo::Caller::VarPropChain",
        "Demo::Caller::VarMethodChain",
        "Demo::Caller::VarNextArray",
    ] {
        assert!(
            run_b_live
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing live caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let run_a_persisted =
        trace_symbol_graph_from_index(&db_path, "Demo::HelperA::RunA", TraceDirection::Callers)
            .unwrap();
    assert_eq!(run_a_persisted.callers.len(), 5);
    for caller in [
        "Demo::Caller::DirectMethodOuter",
        "Demo::Caller::VarMethodOuter",
        "Demo::Caller::PlainDirectProp",
        "Demo::Caller::PlainVarProp",
        "Demo::Caller::PlainDirectMethod",
    ] {
        assert!(
            run_a_persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
    let run_b_persisted =
        trace_symbol_graph_from_index(&db_path, "Demo::HelperB::RunB", TraceDirection::Callers)
            .unwrap();
    assert_eq!(run_b_persisted.callers.len(), 5);
    for caller in [
        "Demo::Caller::DirectPropChain",
        "Demo::Caller::DirectMethodChain",
        "Demo::Caller::VarPropChain",
        "Demo::Caller::VarMethodChain",
        "Demo::Caller::VarNextArray",
    ] {
        assert!(
            run_b_persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
}

#[test]
fn traces_csharp_nested_constructed_generic_receiver_method_call_chain_var_array_element_access_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let db_path = dir.join("symbols.db");
    fs::write(
        dir.join("Types.cs"),
        "namespace Demo;
class HelperA { public int RunA(int value) => value; }
class HelperB { public int RunB(int value) => value; }
class HelperC { public int RunC(int value) => value; }
class Outer<T> {
    public class Inner<U> {
        public U[] Items => default;
        public T[] OuterItems => default;
        public Inner<U> MakeNext() => Next;
        public Inner<U> Next => default;
    }
    public class Middle<U> {
        public class Inner<V> {
            public V[] Items => default;
            public T[] OuterItems => default;
            public Inner<V> MakeNext() => Next;
            public Inner<V> Next => default;
        }
    }
}
class PlainOuter {
    public class PlainInner {
        public HelperA[] Items => default;
        public PlainInner Next => default;
        public PlainInner MakeNext() => Next;
    }
}
class Caller {
    int Chained() { var a = new Outer<HelperA>.Inner<HelperB>().MakeNext(); var arr = a.Items; return arr[0].RunB(1); }
    int ChainedOuter() { var a = new Outer<HelperA>.Inner<HelperB>().MakeNext(); var arr = a.OuterItems; return arr[0].RunA(2); }
    int ChainedDirect() { var a = new Outer<HelperA>.Inner<HelperB>(); var arr = a.Items; return arr[0].RunB(3); }
    int ThreeLevelChain() { var a = new Outer<HelperA>.Middle<HelperB>.Inner<HelperC>().MakeNext(); var arr = a.Items; return arr[0].RunC(4); }
    int ThreeLevelChainOuter() { var a = new Outer<HelperA>.Middle<HelperB>.Inner<HelperC>().MakeNext(); var arr = a.OuterItems; return arr[0].RunA(5); }
    int ThreeLevel() { var arr = new Outer<HelperA>.Middle<HelperB>.Inner<HelperC>().Items; return arr[0].RunC(6); }
    int ThreeLevelOuter() { var arr = new Outer<HelperA>.Middle<HelperB>.Inner<HelperC>().OuterItems; return arr[0].RunA(7); }
    int ThreeLevelDirect() { return new Outer<HelperA>.Middle<HelperB>.Inner<HelperC>().Items[0].RunC(8); }
    int PlainChain() { var a = new PlainOuter.PlainInner().MakeNext(); var arr = a.Items; return arr[0].RunA(9); }
}
",
    )
    .unwrap();

    // A `var` local bound from a method-call chain on a constructed nested
    // generic receiver such as `var a = new Outer<HelperA>.Inner<HelperB>()
    // .MakeNext()` keeps the receiver's concrete generic arguments on the
    // factory marker, so a later member access on the local (`a.Items` or
    // `a.OuterItems` in a separate statement) substitutes the inner type
    // parameter (`U` -> `HelperB`) and an outer-parameter member
    // (`T[] OuterItems` substitutes `T` -> `HelperA`); the same chain
    // through two enclosing generic levels
    // (`Outer<HelperA>.Middle<HelperB>.Inner<HelperC>().MakeNext()`)
    // substitutes `V` -> `HelperC` and `T` -> `HelperA`, direct
    // constructed-receiver chains keep resolving, and non-generic nested
    // chains (`new PlainOuter.PlainInner().MakeNext()`) resolve identically.
    let run_a_live =
        trace_symbol_graph(&dir, "Demo::HelperA::RunA", TraceDirection::Callers).unwrap();
    assert_eq!(run_a_live.callers.len(), 4);
    for caller in [
        "Demo::Caller::ChainedOuter",
        "Demo::Caller::ThreeLevelChainOuter",
        "Demo::Caller::ThreeLevelOuter",
        "Demo::Caller::PlainChain",
    ] {
        assert!(
            run_a_live
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing live RunA caller {caller}"
        );
    }
    let run_b_live =
        trace_symbol_graph(&dir, "Demo::HelperB::RunB", TraceDirection::Callers).unwrap();
    assert_eq!(run_b_live.callers.len(), 2);
    for caller in ["Demo::Caller::Chained", "Demo::Caller::ChainedDirect"] {
        assert!(
            run_b_live
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing live RunB caller {caller}"
        );
    }
    let run_c_live =
        trace_symbol_graph(&dir, "Demo::HelperC::RunC", TraceDirection::Callers).unwrap();
    assert_eq!(run_c_live.callers.len(), 3);
    for caller in [
        "Demo::Caller::ThreeLevelChain",
        "Demo::Caller::ThreeLevel",
        "Demo::Caller::ThreeLevelDirect",
    ] {
        assert!(
            run_c_live
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing live RunC caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let run_a_persisted =
        trace_symbol_graph_from_index(&db_path, "Demo::HelperA::RunA", TraceDirection::Callers)
            .unwrap();
    assert_eq!(run_a_persisted.callers.len(), 4);
    for caller in [
        "Demo::Caller::ChainedOuter",
        "Demo::Caller::ThreeLevelChainOuter",
        "Demo::Caller::ThreeLevelOuter",
        "Demo::Caller::PlainChain",
    ] {
        assert!(
            run_a_persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted RunA caller {caller}"
        );
    }
    let run_b_persisted =
        trace_symbol_graph_from_index(&db_path, "Demo::HelperB::RunB", TraceDirection::Callers)
            .unwrap();
    assert_eq!(run_b_persisted.callers.len(), 2);
    for caller in ["Demo::Caller::Chained", "Demo::Caller::ChainedDirect"] {
        assert!(
            run_b_persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted RunB caller {caller}"
        );
    }
    let run_c_persisted =
        trace_symbol_graph_from_index(&db_path, "Demo::HelperC::RunC", TraceDirection::Callers)
            .unwrap();
    assert_eq!(run_c_persisted.callers.len(), 3);
    for caller in [
        "Demo::Caller::ThreeLevelChain",
        "Demo::Caller::ThreeLevel",
        "Demo::Caller::ThreeLevelDirect",
    ] {
        assert!(
            run_c_persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted RunC caller {caller}"
        );
    }
}
